"use strict";function timeDifference(current,previous){var elapsed=current-previous;return elapsed<6e4?Math.round(elapsed/1e3)+" seconds ago":elapsed<36e5?Math.round(elapsed/6e4)+" minutes ago":elapsed<864e5?Math.round(elapsed/36e5)+" hours ago":elapsed<2592e6?"approximately "+Math.round(elapsed/864e5)+" days ago":elapsed<31536e6?"approximately "+Math.round(elapsed/2592e6)+" months ago":"approximately "+Math.round(elapsed/31536e6)+" years ago"}$(".ac-date").on("click",function(e){$(this).find(".utc,.local").toggleClass("hidden")});